'use strict';

const javaio = require('java.io');

module.exports = create;

function create(clientId, dataId, isTempElement, publishData, unregister) {
  // 注销
  const list = [];
  let revision = 3;
  // 发布
  if (!unregister) {
    revision = 2;
    list.push({
      $: publishData,
      $class: {
        name: 'com.alipay.config.common.protocol.NSwizzle',
        serialVersionUID: '1',
        flags: 3,
        fields: [
          { type: 'I', name: 'serialization' },
          { type: '[', name: 'bytes', classname: '[B' },
          { type: 'L', name: 'object', classname: 'Ljava/lang/Object;' },
        ],
        superClass: null,
      },
    });
  }
  return {
    $: {
      isZip: false,
      needAck: true,
      clientIds: null,
      connId: null,
      data: {
        $: list,
        $class: {
          name: 'java.util.LinkedList',
          serialVersionUID: '876323262645176354',
          flags: 3,
          fields: [],
          superClass: null,
        },
      },
      dataId,
      groupId: null,
      publisherAppName: null,
      publisherEncryptTokens: null,
      revision: {
        $: {
          revision,
        },
        $class: {
          name: 'com.alipay.config.common.NRevision',
          serialVersionUID: '1',
          flags: 2,
          fields: [
            { type: 'J', name: 'revision' },
          ],
          superClass: null,
        },
      },
      subscriberEncryptTokens: null,
      isTempElement: !!isTempElement,
      clientId,
    },
    $class: {
      name: 'com.alipay.config.common.protocol.NPublisherDataElement',
      serialVersionUID: '1',
      flags: 2,
      fields: [
        { type: 'Z', name: 'isTempElement' },
        { type: 'L', name: 'clientId', classname: 'Ljava/lang/String;' },
      ],
      superClass: {
        name: 'com.alipay.config.common.protocol.NUserDataElement',
        serialVersionUID: '1',
        flags: 2,
        fields: [
          { type: 'Z', name: 'isZip' },
          { type: 'Z', name: 'needAck' },
          { type: '[', name: 'clientIds', classname: '[Ljava/lang/String;' },
          { type: 'L', name: 'connId', classname: 'Ljava/lang/String;' },
          { type: 'L', name: 'data', classname: 'Ljava/util/List;' },
          { type: 'L', name: 'dataId', classname: 'Ljava/lang/String;' },
          { type: 'L', name: 'groupId', classname: 'Ljava/lang/String;' },
          { type: 'L', name: 'publisherAppName', classname: 'Ljava/lang/String;' },
          { type: '[', name: 'publisherEncryptTokens', classname: '[[B' },
          { type: 'L', name: 'revision', classname: 'Lcom/alipay/config/common/NRevision;' },
          { type: '[', name: 'subscriberEncryptTokens', classname: '[[B' },
        ],
        superClass: null,
      },
    },
  };
}

javaio.addObject('java.util.LinkedList', {
  readObject(io, obj) {
    io.defaultReadObject(obj);
    io.readBlockHeader();
    const size = io.readInt();
    const items = [];
    for (let i = 0; i < size; i++) {
      items.push(io.readObject());
    }
    obj.$ = items;
    return obj;
  },
  writeObject(io, obj) {
    io.defaultWriteObject(obj);
    io.writeBlockHeader(4);
    const count = obj.$.length;
    io.writeInt(count);
    for (let i = 0; i < count; i++) {
      const item = obj.$[i];
      io.writeObject(item);
    }
  },
});
